/**
 * Creates a debounced version of the provided function.
 *
 * The debounced function will only execute the original function if
 * no further calls are made within the specified delay (`ms`).
 * If a new call is made before the delay has elapsed, the timer is
 * reset and the original function is scheduled to run after the
 * delay from the latest call.
 *
 * The returned function also exposes a `cancel()` method that clears
 * any pending invocation, allowing you to cancel the debounced call
 * if it is no longer needed.
 *
 * @template T - The type of the original function.
 * @param fn - The function to debounce.
 * @param ms - The delay in milliseconds before the function should execute.
 * @returns A debounced function with a `cancel()` method.
 *
 * @example
 * ```ts
 * const debouncedLog = debounce((msg: string) => console.log(msg), 300);
 *
 * debouncedLog("hello");
 * debouncedLog("world");
 * // Only "world" will be logged after 300ms
 *
 * // Cancel any pending invocation
 * debouncedLog.cancel();
 * ```
 */
function debounce<T extends (...args: any[]) => void>(fn: T, ms: number): T & { cancel(): void } {
  let timeoutId: number | null = null;

  const debounced: T & { cancel(): void } = ((...args: any[]) => {
    if (timeoutId !== null) {
      window.clearTimeout(timeoutId);
    }
    timeoutId = window.setTimeout(() => {
      fn(...args);
      timeoutId = null;
    }, ms);
  }) as T & { cancel(): void };

  debounced.cancel = (): void => {
    if (timeoutId !== null) {
      window.clearTimeout(timeoutId);
      timeoutId = null;
    }
  };

  return debounced;
}
